package tr.kasadenge.app;
import android.app.*;import android.os.Bundle;import android.graphics.*;import org.json.*;import java.time.*;import java.util.concurrent.*;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.TextRecognition;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;
public final class CashInstrumentation extends Instrumentation{
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 void check(boolean b,String msg){if(!b)throw new AssertionError(msg);}
 @Override public void onStart(){Bundle result=new Bundle();CashDb db=null;try{
 db=new CashDb(getTargetContext());JSONObject cfg=db.settings();String id="test"+System.currentTimeMillis();cfg.getJSONArray("cashboxes").put(new JSONObject().put("id",id).put("name","Test Kasa").put("advance",150000).put("active",true));db.saveConfig(cfg.toString());
 JSONArray lines=new JSONArray();int[] values={20000,10000,5000,500,500},counts={8,4,2,0,20};for(int i=0;i<values.length;i++)lines.put(new JSONObject().put("id","l"+i).put("label",i==4?"5 TL madeni":values[i]/100+" TL").put("kind",i==4?"coin":"paper").put("value",values[i]).put("count",counts[i]));
 JSONObject raw=new JSONObject().put("cashId",id).put("cashName","Test Kasa").put("date",LocalDate.now().toString()).put("expected",80000).put("advance",150000).put("other",5000).put("lines",lines).put("note","Örnek");
 JSONObject r=db.closeCount(raw.toString());check(r.getLong("diff")==-5000&&r.getLong("remaining")==10000,"golden arithmetic");int n=db.rows("entries").length();try{db.closeCount(raw.toString());throw new AssertionError("silent duplicate");}catch(Exception expected){}
 raw.put("reason","Yeniden sayıldı").put("baseRevision",1);r=db.closeCount(raw.toString());check(r.getInt("revision")==2&&db.rows("entries").length()==n,"single closing after correction");check(db.rows("revisions").length()>0,"revision history missing");try{db.closeCount(raw.toString());throw new AssertionError("stale revision accepted");}catch(Exception expected){}
 cfg=db.settings();for(int i=0;i<cfg.getJSONArray("cashboxes").length();i++)if(cfg.getJSONArray("cashboxes").getJSONObject(i).getString("id").equals(id))cfg.getJSONArray("cashboxes").getJSONObject(i).put("advance",200000);db.saveConfig(cfg.toString());check(db.find(r.getString("id")).getLong("advance")==150000,"historical float modified");
 String backup=db.state().toString();db.merge(backup);check(db.rows("entries").length()==n,"backup doubled records");try{db.merge("{\"app\":\"kasadenge\",\"schema\":2}");throw new AssertionError("bad backup accepted");}catch(Exception expected){}check(db.rows("entries").length()==n,"bad import damaged records");
 JSONObject pos=new JSONObject().put("cashId",id).put("cashName","Test Kasa").put("date","2026-10-01").put("terminal","Test POS").put("lines",new JSONArray().put(new JSONObject().put("type","creditDomestic").put("label","Kredi").put("amount",4312763)).put(new JSONObject().put("type","debitDomestic").put("label","Debit").put("amount",1691245)));JSONObject pr=db.savePos(pos.toString());check(pr.getLong("total")==6004008,"POS sum");check(pr.getJSONArray("lines").getJSONObject(0).getString("due").equals("2026-10-22"),"credit due");check(pr.getJSONArray("lines").getJSONObject(1).getString("due").equals("2026-10-16"),"debit due");int pn=db.rows("pos").length();try{db.savePos(pos.toString());throw new AssertionError("POS duplicate accepted");}catch(Exception expected){}pos.put("baseRevision",1).put("reason","Fiş düzeltildi");db.savePos(pos.toString());check(db.rows("pos").length()==pn&&db.rows("pos_revisions").length()>0,"POS correction doubled or lost archive");try{db.savePos(pos.toString());throw new AssertionError("POS stale accepted");}catch(Exception expected){}db.merge(db.state().toString());check(db.rows("pos").length()==pn,"POS backup duplicate");
 result.putString("database","PASS POS due dates, duplicate guard, correction archive, stale rejection, backup dedup; real SQLite arithmetic, duplicate guard, revision, stale edit rejection, float snapshots, backup dedup and failed import atomicity");
 Bitmap bitmap=Bitmap.createBitmap(1400,700,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(Color.WHITE);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.BLACK);p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));p.setTextSize(72);canvas.drawText("Beklenen tutar: 800",50,140,p);canvas.drawText("Avans: 1500",50,300,p);canvas.drawText("200 TL x 8",50,460,p);
 CountDownLatch done=new CountDownLatch(1);String[] text={null};com.google.mlkit.vision.text.TextRecognizer ocr=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);ocr.process(InputImage.fromBitmap(bitmap,0)).addOnSuccessListener(t->{text[0]=t.getText();done.countDown();}).addOnFailureListener(e->{text[0]="ERROR "+e;done.countDown();});check(done.await(120,TimeUnit.SECONDS),"OCR timeout");ocr.close();bitmap.recycle();check(text[0]!=null&&text[0].contains("800")&&text[0].contains("1500"),"OCR evidence missing: "+text[0]);result.putString("ocr","PASS on-device bundled OCR on synthetic printed cashbook text: "+text[0]);result.putString("stream",result.getString("database")+"\n"+result.getString("ocr")+"\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL "+e+"\n");finish(Activity.RESULT_CANCELED,result);}finally{if(db!=null)db.close();}}
}
